mapper.select:
SELECT b.id, b.user_id, b.file_id, b.display_title, b.progress_cfi, b.progress_percent, b.last_read_at, b.created_at, f.file_type, f.file_size, f.meta_title, f.meta_author FROM bookshelf_item b LEFT JOIN file_asset f ON b.file_id = f.id WHERE b.user_id = #{userId}
AND b.display_title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY b.last_read_at DESC, b.created_at DESC

mapper.update:
UPDATE bookshelf_item
SET display_title = #{displayTitle}
WHERE id = #{id}

UPDATE bookshelf_item
SET progress_cfi = #{progressCfi},
    progress_percent = #{progressPercent},
    last_read_at = #{lastReadAt}
WHERE id = #{id}
